	void BeginVRMenuPresentationTraceProducerPass(uint32_t a_session, uint32_t a_menuMask);
	void FlushVRMenuPresentationTraceProducerPass(std::string_view a_reason);
	void FlushVRMenuPresentationTraceGlobalOutputPass(std::string_view a_reason);
	void ResetVRMenuPresentationTraceGenerations();
	std::string GetVRMenuPresentationTraceScopeDescription();
	template <class DetailBuilder>
	void LogVRMenuPresentationTraceLazy(std::string_view a_event, DetailBuilder&& a_buildDetails) noexcept;

	void ArmVRMenuPresentationTrace(std::string_view a_triggerMenu, uint32_t a_menuMask)
	{
		if (!globals::game::isVR || a_menuMask == 0)
			return;
		if (!ShouldEmitUpscalingDiagLogs()) {
			FlushVRMenuPresentationTraceProducerPass("developer-mode-disabled");
			FlushVRMenuPresentationTraceGlobalOutputPass("developer-mode-disabled");
			g_vrMenuPresentationTraceMenuMask.store(0, std::memory_order_release);
			g_vrMenuPresentationTraceDiagnosticsEnabled.store(false, std::memory_order_relaxed);
			return;
		}
		g_vrMenuPresentationTraceDiagnosticsEnabled.store(true, std::memory_order_relaxed);

		FlushVRMenuPresentationTraceProducerPass("session-rearm");
		FlushVRMenuPresentationTraceGlobalOutputPass("session-rearm");
		g_vrMenuPresentationTraceMenuMask.store(0, std::memory_order_release);
		uint32_t session = 0;
		uint64_t sequence = 0;
		const uint32_t frame = GetVRMenuPresentationTraceFrame();
		{
			std::scoped_lock recordLock(g_vrMenuPresentationTraceRecordMutex);
			session = g_vrMenuPresentationTraceSession.fetch_add(1, std::memory_order_acq_rel) + 1u;
			g_vrMenuPresentationTraceRecordsThisSession.store(1, std::memory_order_release);
			g_vrMenuPresentationTraceSessionCapLogged.store(false, std::memory_order_release);
			g_vrMenuPresentationTraceFaulted.store(false, std::memory_order_release);
			g_vrMenuPresentationTraceFaultLogged.store(false, std::memory_order_release);
			sequence = g_vrMenuPresentationTraceSequence.fetch_add(1, std::memory_order_acq_rel) + 1u;
		}
		ResetVRMenuPresentationTraceCounters();
		g_vrMenuPresentationTraceMapDrawOrdinal.store(0, std::memory_order_release);
		g_vrMenuPresentationTraceMapResourceOperationOrdinal.store(0, std::memory_order_release);
		g_vrMenuPresentationTraceLastAccumulatorEpochId.store(0, std::memory_order_release);
		g_vrMenuPresentationTraceLastCompositionEpochId.store(0, std::memory_order_release);
		g_vrMenuPresentationTraceLastBridgeEpochId.store(0, std::memory_order_release);
		g_vrMenuPresentationTraceObservedMenuMask.store(a_menuMask, std::memory_order_release);
		{
			std::scoped_lock sessionLock(g_vrMenuPresentationTraceSessionMutex);
			g_vrMenuPresentationTraceTriggerMenu = a_triggerMenu;
			g_vrMenuPresentationTraceStartFrame = frame;
			g_vrMenuPresentationTraceStartMenuMask = a_menuMask;
		}
		logger::debug(
			"[VRMenuTrace] session={} seq={} frame={} event=session-begin trigger=\"{}\" menus=\"{}\" d3dHooksInstalled={} d3dHookBanks={} createDeferredContextHook={} recordCap={} capBehavior=counter-only requiredRecordsContinue=true perRecordFlush=false globalOutputFlush=session-boundary outsideDrawRecords=complete accumulatorEpochRecords=complete allDrawEpochAccounting=self-calibrating generationCorrelation=enabled generationHistory=preserved-across-session bridgePipelineState=complete mapDetailedStream=relevant-plus-1-in-256-unrelated-and-all-resource-operations commandListCorrelation=enabled",
			session,
			sequence,
			frame,
			a_triggerMenu,
			DescribeVRMenuPresentationTraceMenuMask(a_menuMask),
			g_vrMenuPresentationTraceD3DHooksInstalled.load(std::memory_order_acquire),
			g_vrMenuPresentationTraceD3DHookBanksInstalled.load(std::memory_order_acquire),
			g_vrMenuPresentationTraceCreateDeferredContextHookInstalled.load(std::memory_order_acquire),
			kVRMenuPresentationTraceMaxRecordsPerSession);
		FlushVRMenuPresentationTraceLog();
		g_vrMenuPresentationTraceMenuMask.store(a_menuMask, std::memory_order_release);
		if (g_vrMenuPresentationTraceDrawInterfaceDepth != 0)
			BeginVRMenuPresentationTraceProducerPass(session, a_menuMask);
	}

	void StopVRMenuPresentationTraceRaceSexPreRoll(std::string_view a_reason)
	{
		const bool wasActive =
			g_vrMenuPresentationTraceRaceSexPreRollActive.exchange(false, std::memory_order_acq_rel);
		g_vrMenuPresentationTraceRaceSexPreRollEndFrame.store(0, std::memory_order_release);
		if (!wasActive)
			return;

		const uint32_t previousMenuMask =
			g_vrMenuPresentationTraceMenuMask.load(std::memory_order_acquire);
		if ((previousMenuMask & kVRMenuPresentationTraceRaceSexPreRollBit) == 0)
			return;
		const uint32_t newMenuMask = previousMenuMask & ~kVRMenuPresentationTraceRaceSexPreRollBit;
		FlushVRMenuPresentationTraceProducerPass("racesex-preroll-stop");
		FlushVRMenuPresentationTraceGlobalOutputPass("racesex-preroll-stop");
		LogVRMenuPresentationTraceLazy(
			"menu-event",
			[&]() { return std::format(
						"menu=\"RaceSexPreRoll\" opening=false reason={} presentationBit=0x{:X} menus=\"{}\" {}",
						a_reason,
						kVRMenuPresentationTraceRaceSexPreRollBit,
						DescribeVRMenuPresentationTraceMenuMask(newMenuMask),
						GetVRMenuPresentationTraceScopeDescription()); });
		g_vrMenuPresentationTraceMenuMask.store(0, std::memory_order_release);
		LogVRMenuPresentationTraceSummary(
			"racesex-preroll-stop",
			a_reason,
			newMenuMask);
		if (newMenuMask != 0)
			ArmVRMenuPresentationTrace("continuation-after-racesex-preroll", newMenuMask);
	}

	void StartVRMenuPresentationTraceRaceSexPreRoll(uint32_t a_frame)
	{
		if (!globals::game::isVR || !ShouldEmitUpscalingDiagLogs() ||
			!g_vrMenuPresentationTraceRaceSexPreRollPending.exchange(false, std::memory_order_acq_rel)) {
			return;
		}

		const uint32_t endFrame = a_frame + kVRMenuPresentationTraceRaceSexPreRollFrames;
		g_vrMenuPresentationTraceRaceSexPreRollEndFrame.store(endFrame, std::memory_order_release);
		g_vrMenuPresentationTraceRaceSexPreRollActive.store(true, std::memory_order_release);
		const uint32_t previousMenuMask =
			g_vrMenuPresentationTraceMenuMask.load(std::memory_order_acquire);
		const uint32_t newMenuMask = previousMenuMask | kVRMenuPresentationTraceRaceSexPreRollBit;
		if (previousMenuMask != 0) {
			FlushVRMenuPresentationTraceProducerPass("racesex-preroll-start");
			FlushVRMenuPresentationTraceGlobalOutputPass("racesex-preroll-start");
			g_vrMenuPresentationTraceMenuMask.store(0, std::memory_order_release);
			LogVRMenuPresentationTraceSummary(
				"racesex-preroll-start",
				"RaceSexPreRoll",
				previousMenuMask);
		}
		ArmVRMenuPresentationTrace("racesex-preroll", newMenuMask);
		LogVRMenuPresentationTraceLazy(
			"menu-event",
			[&]() { return std::format(
						"menu=\"RaceSexPreRoll\" opening=true presentationBit=0x{:X} startFrame={} endFrame={} menus=\"{}\" {}",
						kVRMenuPresentationTraceRaceSexPreRollBit,
						a_frame,
						endFrame,
						DescribeVRMenuPresentationTraceMenuMask(newMenuMask),
						GetVRMenuPresentationTraceScopeDescription()); });
	}

	void ServiceVRMenuPresentationTraceRaceSexPreRoll()
	{
		if (!ShouldEmitUpscalingDiagLogs())
			return;

		if (!g_vrMenuPresentationTraceRaceSexPreRollActive.load(std::memory_order_acquire)) {
			if (g_vrMenuPresentationTraceRaceSexPreRollPending.load(std::memory_order_acquire) &&
				GetVRStartupLoadKind() == VRStartupLoadKind::NewGame &&
				g_vrLoadingTransitionCloseFrame.load(std::memory_order_acquire) != 0 &&
				!g_vrRaceSexMenuOpenFromEvent.load(std::memory_order_acquire)) {
				StartVRMenuPresentationTraceRaceSexPreRoll(GetVRMenuPresentationTraceFrame());
			}
			return;
		}
		const uint32_t frame = GetVRMenuPresentationTraceFrame();
		const uint32_t endFrame =
			g_vrMenuPresentationTraceRaceSexPreRollEndFrame.load(std::memory_order_acquire);
		if (endFrame != 0 && frame >= endFrame)
			StopVRMenuPresentationTraceRaceSexPreRoll("expired-before-racesex-open");
	}

	bool IsVRMenuPresentationTraceEventRetained(std::string_view a_event)
	{
		return a_event == "menu-event" ||
		       a_event == "draw-interface-begin" ||
		       a_event == "draw-interface-end" ||
		       a_event == "menu-accumulator-begin" ||
		       a_event == "menu-accumulator-end" ||
		       a_event == "menu-producer-pass" ||
		       a_event == "menu-output-pass" ||
		       a_event == "menu-output-sample" ||
		       a_event == "menu-output-draw" ||
		       a_event == "menu-resource-operation" ||
		       a_event == "menu-generation-reset" ||
		       a_event == "map-draw" ||
		       a_event == "map-resource-operation" ||
		       a_event == "menu-layer-lifecycle" ||
		       a_event == "menu-composition-draw" ||
		       a_event == "bridge-decision" ||
		       a_event == "final-composite" ||
		       a_event == "openvr-submit";
	}

	void ReportVRMenuPresentationTraceFault(const char* a_context, const char* a_detail = nullptr) noexcept
	{
		g_vrMenuPresentationTraceFaulted.store(true, std::memory_order_release);
		if (g_vrMenuPresentationTraceFaultLogged.exchange(true, std::memory_order_acq_rel))
			return;

		try {
			if (a_detail) {
				logger::error(
					"[VRMenuTrace] A diagnostic record failed {}; tracing will continue so later required evidence is retained: {}",
					a_context,
					a_detail);
			} else {
				logger::error(
					"[VRMenuTrace] A diagnostic record failed {}; tracing will continue so later required evidence is retained.",
					a_context);
			}
		} catch (...) {
		}
	}

	bool TryBeginVRMenuPresentationTraceRecord(
		uint32_t& a_outSession,
		uint32_t& a_outFrame,
		uint64_t& a_outSequence)
	{
		if (!IsVRMenuPresentationTraceActive())
			return false;

		bool logSessionCap = false;
		{
			std::scoped_lock lock(g_vrMenuPresentationTraceRecordMutex);
			a_outSession = g_vrMenuPresentationTraceSession.load(std::memory_order_acquire);
			a_outFrame = GetVRMenuPresentationTraceFrame();
			g_vrMenuPresentationTraceObservedMenuMask.fetch_or(
				g_vrMenuPresentationTraceMenuMask.load(std::memory_order_acquire),
				std::memory_order_acq_rel);

			const uint32_t sessionRecords =
				g_vrMenuPresentationTraceRecordsThisSession.load(std::memory_order_acquire);
			if (sessionRecords >= kVRMenuPresentationTraceMaxRecordsPerSession) {
				logSessionCap = !g_vrMenuPresentationTraceSessionCapLogged.exchange(true, std::memory_order_acq_rel);
			}

			if (sessionRecords < kVRMenuPresentationTraceMaxRecordsPerSession)
				g_vrMenuPresentationTraceRecordsThisSession.store(sessionRecords + 1u, std::memory_order_release);
			a_outSequence = g_vrMenuPresentationTraceSequence.fetch_add(1, std::memory_order_acq_rel) + 1u;
		}

		if (logSessionCap) {
			logger::debug(
				"[VRMenuTrace] session={} record-cap={} reached; the retained-record counter is saturated but no required lifecycle, pass, operation, or consumer records will be dropped",
				a_outSession,
				kVRMenuPresentationTraceMaxRecordsPerSession);
		}
		return true;
	}
	template <class DetailBuilder>
	void LogVRMenuPresentationTraceLazy(
		std::string_view a_event,
		DetailBuilder&& a_buildDetails) noexcept
	{
		// Most production paths retain their diagnostic call sites after Debug is
		// disabled. Reject them before scanning event names or building details.
		if (!IsVRMenuPresentationTraceActive() || !IsVRMenuPresentationTraceEventRetained(a_event))
			return;

		try {
			uint32_t session = 0;
			uint32_t frame = 0;
			uint64_t sequence = 0;
			if (!TryBeginVRMenuPresentationTraceRecord(session, frame, sequence))
				return;

			logger::debug(
				"[VRMenuTrace] session={} seq={} frame={} event={} {}",
				session,
				sequence,
				frame,
				a_event,
				a_buildDetails());
		} catch (const std::exception& e) {
			ReportVRMenuPresentationTraceFault("after an exception", e.what());
		} catch (...) {
			ReportVRMenuPresentationTraceFault("after an unknown exception");
		}
	}

	VRMenuPresentationTraceAccumulatorContext* GetCurrentVRMenuPresentationTraceAccumulatorContext()
	{
		if (g_vrMenuPresentationTraceAccumulatorDepth == 0 ||
			g_vrMenuPresentationTraceUntrackedAccumulatorDepth != 0) {
			return nullptr;
		}
		if (g_vrMenuPresentationTraceAccumulatorDepth > kVRMenuPresentationTraceMaxAccumulatorDepth) {
			return g_vrMenuPresentationTraceAccumulatorOverflowStack.empty() ?
			           nullptr :
			           &g_vrMenuPresentationTraceAccumulatorOverflowStack.back();
		}

		return &g_vrMenuPresentationTraceAccumulatorStack[g_vrMenuPresentationTraceAccumulatorDepth - 1u];
	}

	uint32_t GetCurrentVRMenuPresentationTraceAccumulatorMode()
	{
		const auto* context = GetCurrentVRMenuPresentationTraceAccumulatorContext();
		return context ? context->renderMode : kVRMenuPresentationTraceUnknownRenderMode;
	}

	uint64_t GetCurrentVRMenuPresentationTraceAccumulatorEpochId()
	{
		const auto* context = GetCurrentVRMenuPresentationTraceAccumulatorContext();
		return context ? context->epochId : 0u;
	}

	void RecordVRMenuPresentationTraceAccumulatorHigherCall()
	{
		if (auto* context = GetCurrentVRMenuPresentationTraceAccumulatorContext()) {
			context->relevant = true;
			++context->higherCallEntries;
		}
	}

	void RecordVRMenuPresentationTraceAccumulatorBridgeDecision()
	{
		if (auto* context = GetCurrentVRMenuPresentationTraceAccumulatorContext()) {
			context->relevant = true;
			if (context->bridgeDecisions != 0) {
				context->unrelatedBetweenBridges += context->unrelatedSinceLastBridge;
				context->unrelatedSinceLastBridge = 0;
			}
			++context->bridgeDecisions;
		}
	}

	void TrackVRMenuPresentationTraceAccumulatorDrawContext(
		VRMenuPresentationTraceAccumulatorContext& a_context,
		ID3D11DeviceContext* a_d3dContext)
	{
		if (!a_d3dContext)
			return;

		const auto contextIdentity = reinterpret_cast<std::uintptr_t>(a_d3dContext);
		const auto vtableIdentity = reinterpret_cast<std::uintptr_t>(
			*reinterpret_cast<std::uintptr_t**>(a_d3dContext));
		for (uint32_t index = 0; index < a_context.drawContextCount; ++index) {
			if (a_context.drawContextIdentities[index] == contextIdentity &&
				a_context.drawVtableIdentities[index] == vtableIdentity) {
				return;
			}
		}

		if (a_context.drawContextCount >= a_context.drawContextIdentities.size()) {
			a_context.drawContextOverflow = true;
			return;
		}

		const uint32_t index = a_context.drawContextCount++;
		a_context.drawContextIdentities[index] = contextIdentity;
		a_context.drawVtableIdentities[index] = vtableIdentity;
	}

	void RecordVRMenuPresentationTraceAccumulatorDirectBridgeDraw(
		ID3D11DeviceContext* a_context,
		bool a_coverageAtEntry,
		bool a_coverageAfterInstall)
	{
		if (auto* context = GetCurrentVRMenuPresentationTraceAccumulatorContext()) {
			context->relevant = true;
			++context->directBridgeDraws;
			TrackVRMenuPresentationTraceAccumulatorDrawContext(*context, a_context);
			context->drawHookCoverageChanged = context->drawHookCoverageChanged ||
			                                   (!a_coverageAtEntry && a_coverageAfterInstall);
			context->drawHookCoverageFailed = context->drawHookCoverageFailed || !a_coverageAfterInstall;
		}
	}

	void RecordVRMenuPresentationTraceAccumulatorDirectBridgeDrawOutcome(bool a_suppressed)
	{
		if (auto* context = GetCurrentVRMenuPresentationTraceAccumulatorContext()) {
			if (a_suppressed) {
				++context->directBridgeDrawsSuppressed;
			} else {
				++context->directBridgeDrawsIssued;
			}
		}
	}

	void InvalidateVRMenuPresentationTraceAccumulatorDrawAccounting()
	{
		if (auto* context = GetCurrentVRMenuPresentationTraceAccumulatorContext())
			context->drawHookCoverageFailed = true;
	}

	std::string GetVRMenuPresentationTraceScopeDescription()
	{
		const auto* state = globals::state;
		return std::format(
			"scope(drawInterface={},higher={},direct={},accumulator={},epoch={},renderMode={}) correlation(lastAccumulatorEpoch={},lastCompositionEpoch={},lastBridgeEpoch={}) context(menuMask=0x{:X},main={},loading={},map={},raceSexEvent={},renderScaleActive={},presentationUpscaling={})",
			g_vrMenuPresentationTraceDrawInterfaceDepth,
			g_vrMenuPresentationTraceHigherCallDepth,
			g_vrMenuPresentationTraceDirectDrawDepth,
			g_vrMenuPresentationTraceAccumulatorDepth,
			GetCurrentVRMenuPresentationTraceAccumulatorEpochId(),
			GetCurrentVRMenuPresentationTraceAccumulatorMode(),
			g_vrMenuPresentationTraceLastAccumulatorEpochId.load(std::memory_order_acquire),
			g_vrMenuPresentationTraceLastCompositionEpochId.load(std::memory_order_acquire),
			g_vrMenuPresentationTraceLastBridgeEpochId.load(std::memory_order_acquire),
			g_vrMenuPresentationTraceMenuMask.load(std::memory_order_acquire),
			state && state->isMainMenuOpen,
			(state && state->isLoadingMenuOpen) ||
				g_vrLoadingMenuOpenFromEvent.load(std::memory_order_relaxed),
			(state && state->isMapMenuOpen) ||
				g_vrMapMenuOpenFromEvent.load(std::memory_order_relaxed),
			g_vrRaceSexMenuOpenFromEvent.load(std::memory_order_relaxed),
			globals::features::upscaling.IsVRRenderScaleModeActive(),
			globals::features::upscaling.IsPresentationUpscalingActive());
	}

	std::string DescribeVRMenuPresentationTraceResource(ID3D11Resource* a_resource)
	{
		if (!a_resource)
			return "null";

		const auto info = ResolveVRMenuPresentationTraceResource(a_resource);
		std::string owner = "unregistered";
		if (info.renderTargetIndex >= 0) {
			owner = std::format(
				"rt={}({}){}",
				GetVRMenuPresentationTraceRenderTargetName(info.renderTargetIndex),
				info.renderTargetIndex,
				info.textureCopy ? ".copy" : "");
		} else if (info.depthStencilIndex >= 0) {
			owner = std::format(
				"ds={}({})",
				GetVRMenuPresentationTraceDepthTargetName(info.depthStencilIndex),
				info.depthStencilIndex);
		}

		if (!info.hasTextureDesc) {
			return std::format(
				"{} id=0x{:X}",
				owner,
				info.identity);
		}

		return std::format(
			"{} id=0x{:X} size={}x{} array={} mips={} samples={} format={}",
			owner,
			info.identity,
			info.desc.Width,
			info.desc.Height,
			info.desc.ArraySize,
			info.desc.MipLevels,
			info.desc.SampleDesc.Count,
			static_cast<uint32_t>(info.desc.Format));
	}

	std::string DescribeVRMenuPresentationTraceView(ID3D11View* a_view)
	{
		if (!a_view)
			return "null";

		ID3D11Resource* resource = nullptr;
		a_view->GetResource(&resource);
		auto releaseResource = ScopeExit([&]() {
			if (resource)
				resource->Release();
		});
		return std::format(
			"view=0x{:X} {}",
			GetCOMIdentityAddress(a_view),
			DescribeVRMenuPresentationTraceResource(resource));
	}

	std::string DescribeVRMenuPresentationTraceOutputs(ID3D11DeviceContext* a_context)
	{
		if (!a_context)
			return "outputs=null-context";

		std::array<ID3D11RenderTargetView*, D3D11_SIMULTANEOUS_RENDER_TARGET_COUNT> rtvs{};
		ID3D11DepthStencilView* dsv = nullptr;
		a_context->OMGetRenderTargets(static_cast<UINT>(rtvs.size()), rtvs.data(), &dsv);
		auto releaseViews = ScopeExit([&]() {
			for (auto* rtv : rtvs) {
				if (rtv)
					rtv->Release();
			}
			if (dsv)
				dsv->Release();
		});

		std::string description = "rtvs=[";
		bool first = true;
		for (uint32_t slot = 0; slot < rtvs.size(); ++slot) {
			if (!rtvs[slot])
				continue;
			if (!first)
				description += "; ";
			description += std::format("{}:{}", slot, DescribeVRMenuPresentationTraceView(rtvs[slot]));
			first = false;
		}
		description += std::format("] dsv={}", DescribeVRMenuPresentationTraceView(dsv));
		return description;
	}

	// Mirror PSSet updates for normal filtered tracing. Candidate accumulator
	// epochs refresh all slots per draw so unrelated-draw counts cannot inherit
	// stale source bindings.
	struct VRMenuPresentationTracePSBindingCache
	{
		ID3D11DeviceContext* context = nullptr;
		uint32_t session = 0;
		uint32_t sourceCount = 0;
		bool initialized = false;
		std::array<VRMenuCompositionTargetMatch, D3D11_COMMONSHADER_INPUT_RESOURCE_SLOT_COUNT> sources{};
	};
	thread_local VRMenuPresentationTracePSBindingCache g_vrMenuPresentationTracePSBindingCache{};

	bool IsVRMenuPresentationTraceCompositionSource(const VRMenuCompositionTargetMatch& a_match)
	{
		if (!a_match.matched)
			return false;
		return a_match.target == RE::RENDER_TARGETS::kPROJECTEDMENU ||
		       a_match.target == RE::RENDER_TARGETS::kHUDMENU;
	}

	bool IsVRMenuWorldUITraceSource(const VRMenuCompositionTargetMatch& a_match)
	{
		if (!a_match.matched)
			return false;
		return a_match.target == RE::RENDER_TARGETS::kWORLDUI0 ||
		       a_match.target == RE::RENDER_TARGETS::kWORLDUI1;
	}

	VRMenuCompositionTargetMatch ResolveVRMenuPresentationTraceCompositionSource(ID3D11ShaderResourceView* a_view)
	{
		VRMenuCompositionTargetMatch match{};
		if (!TryResolveVRMenuCompositionView(a_view, match) || !IsVRMenuPresentationTraceCompositionSource(match))
			return {};
		return match;
	}

	void RefreshVRMenuPresentationTracePSBindingCache(ID3D11DeviceContext* a_context)
	{
		auto& cache = g_vrMenuPresentationTracePSBindingCache;
		cache = {};
		if (!a_context)
			return;

		cache.context = a_context;
		cache.session = g_vrMenuPresentationTraceSession.load(std::memory_order_acquire);
		std::array<ID3D11ShaderResourceView*, D3D11_COMMONSHADER_INPUT_RESOURCE_SLOT_COUNT> views{};
		a_context->PSGetShaderResources(0, static_cast<UINT>(views.size()), views.data());
		for (uint32_t slot = 0; slot < views.size(); ++slot) {
			cache.sources[slot] = ResolveVRMenuPresentationTraceCompositionSource(views[slot]);
			if (IsVRMenuPresentationTraceCompositionSource(cache.sources[slot]))
				++cache.sourceCount;
			if (views[slot])
				views[slot]->Release();
		}
		cache.initialized = true;
	}

	void TrackVRMenuPresentationTracePSBindings(
		ID3D11DeviceContext* a_context,
		UINT a_startSlot,
		UINT a_viewCount,
		ID3D11ShaderResourceView* const* a_views) noexcept
	{
		try {
			if (!IsVRMenuPresentationTraceActive())
				return;

			auto& cache = g_vrMenuPresentationTracePSBindingCache;
			const uint32_t session = g_vrMenuPresentationTraceSession.load(std::memory_order_acquire);
			if (!cache.initialized || cache.context != a_context || cache.session != session)
				return;
			if (a_startSlot >= cache.sources.size())
				return;

			const uint32_t trackedViewCount = std::min<uint32_t>(
				a_viewCount,
				static_cast<uint32_t>(cache.sources.size()) - a_startSlot);
			const uint32_t endSlot = a_startSlot + trackedViewCount;
			for (uint32_t slot = a_startSlot; slot < endSlot; ++slot) {
				const uint32_t viewIndex = slot - a_startSlot;
				const bool hadSource = IsVRMenuPresentationTraceCompositionSource(cache.sources[slot]);
				cache.sources[slot] = ResolveVRMenuPresentationTraceCompositionSource(
					a_views ? a_views[viewIndex] : nullptr);
				const bool hasSource = IsVRMenuPresentationTraceCompositionSource(cache.sources[slot]);
				if (hasSource && !hadSource) {
					++cache.sourceCount;
				} else if (hadSource && !hasSource && cache.sourceCount != 0) {
					--cache.sourceCount;
				}
			}
		} catch (const std::exception& e) {
			ReportVRMenuPresentationTraceFault("while tracking PS bindings", e.what());
		} catch (...) {
			ReportVRMenuPresentationTraceFault("while tracking PS bindings");
		}
	}

	struct VRMenuPresentationTraceDepthStateDescription
	{
		std::string text;
		bool enabled = false;
		bool writes = false;
		bool stencil = false;
	};

	VRMenuPresentationTraceDepthStateDescription DescribeVRMenuPresentationTraceDepthState(
		ID3D11DeviceContext* a_context,
		bool a_includeText = true)
	{
		VRMenuPresentationTraceDepthStateDescription result{};
		if (!a_context) {
			result.text = "depth=null-context";
			return result;
		}

		ID3D11DepthStencilState* state = nullptr;
		UINT stencilRef = 0;
		a_context->OMGetDepthStencilState(&state, &stencilRef);
		auto releaseState = ScopeExit([&]() {
			if (state)
				state->Release();
		});

		D3D11_DEPTH_STENCIL_DESC desc{};
		desc.DepthEnable = TRUE;
		desc.DepthWriteMask = D3D11_DEPTH_WRITE_MASK_ALL;
		desc.DepthFunc = D3D11_COMPARISON_LESS;
		desc.StencilEnable = FALSE;
		desc.StencilReadMask = static_cast<UINT8>(D3D11_DEFAULT_STENCIL_READ_MASK);
		desc.StencilWriteMask = static_cast<UINT8>(D3D11_DEFAULT_STENCIL_WRITE_MASK);
		desc.FrontFace = {
			D3D11_STENCIL_OP_KEEP,
			D3D11_STENCIL_OP_KEEP,
			D3D11_STENCIL_OP_KEEP,
			D3D11_COMPARISON_ALWAYS,
		};
		desc.BackFace = desc.FrontFace;
		if (state)
			state->GetDesc(&desc);

		result.enabled = desc.DepthEnable != FALSE;
		result.writes = result.enabled && desc.DepthWriteMask != D3D11_DEPTH_WRITE_MASK_ZERO;
		result.stencil = desc.StencilEnable != FALSE;
		if (a_includeText) {
			result.text = std::format(
				"depth(state=0x{:X},default={},enabled={},writeMask={},func={},stencil(enabled={},readMask={},writeMask={},ref={},front(fail={},depthFail={},pass={},func={}),back(fail={},depthFail={},pass={},func={})))",
				GetCOMIdentityAddress(state),
				state == nullptr,
				result.enabled,
				static_cast<uint32_t>(desc.DepthWriteMask),
				static_cast<uint32_t>(desc.DepthFunc),
				result.stencil,
				static_cast<uint32_t>(desc.StencilReadMask),
				static_cast<uint32_t>(desc.StencilWriteMask),
				stencilRef,
				static_cast<uint32_t>(desc.FrontFace.StencilFailOp),
				static_cast<uint32_t>(desc.FrontFace.StencilDepthFailOp),
				static_cast<uint32_t>(desc.FrontFace.StencilPassOp),
				static_cast<uint32_t>(desc.FrontFace.StencilFunc),
				static_cast<uint32_t>(desc.BackFace.StencilFailOp),
				static_cast<uint32_t>(desc.BackFace.StencilDepthFailOp),
				static_cast<uint32_t>(desc.BackFace.StencilPassOp),
				static_cast<uint32_t>(desc.BackFace.StencilFunc));
		}
		return result;
	}

	std::string DescribeVRMenuPresentationTraceBridgePipelineState(ID3D11DeviceContext* a_context)
	{
		if (!a_context)
			return "pipeline=null-context";

		ID3D11BlendState* blendState = nullptr;
		std::array<FLOAT, 4> blendFactor{};
		UINT sampleMask = 0;
		a_context->OMGetBlendState(&blendState, blendFactor.data(), &sampleMask);
		auto releaseBlendState = ScopeExit([&]() {
			if (blendState)
				blendState->Release();
		});
		D3D11_BLEND_DESC blendDesc{};
		for (auto& target : blendDesc.RenderTarget) {
			target.BlendEnable = FALSE;
			target.SrcBlend = D3D11_BLEND_ONE;
			target.DestBlend = D3D11_BLEND_ZERO;
			target.BlendOp = D3D11_BLEND_OP_ADD;
			target.SrcBlendAlpha = D3D11_BLEND_ONE;
			target.DestBlendAlpha = D3D11_BLEND_ZERO;
			target.BlendOpAlpha = D3D11_BLEND_OP_ADD;
			target.RenderTargetWriteMask = static_cast<UINT8>(D3D11_COLOR_WRITE_ENABLE_ALL);
		}
		if (blendState)
			blendState->GetDesc(&blendDesc);

		std::string blendTargets;
		for (uint32_t index = 0; index < D3D11_SIMULTANEOUS_RENDER_TARGET_COUNT; ++index) {
			if (!blendTargets.empty())
				blendTargets += ';';
			const auto& target = blendDesc.RenderTarget[index];
			blendTargets += std::format(
				"{}(enabled={},src={},dst={},op={},srcAlpha={},dstAlpha={},opAlpha={},writeMask=0x{:X})",
				index,
				target.BlendEnable != FALSE,
				static_cast<uint32_t>(target.SrcBlend),
				static_cast<uint32_t>(target.DestBlend),
				static_cast<uint32_t>(target.BlendOp),
				static_cast<uint32_t>(target.SrcBlendAlpha),
				static_cast<uint32_t>(target.DestBlendAlpha),
				static_cast<uint32_t>(target.BlendOpAlpha),
				static_cast<uint32_t>(target.RenderTargetWriteMask));
		}

		ID3D11RasterizerState* rasterizerState = nullptr;
		a_context->RSGetState(&rasterizerState);
		auto releaseRasterizerState = ScopeExit([&]() {
			if (rasterizerState)
				rasterizerState->Release();
		});
		D3D11_RASTERIZER_DESC rasterizerDesc{};
		rasterizerDesc.FillMode = D3D11_FILL_SOLID;
		rasterizerDesc.CullMode = D3D11_CULL_BACK;
		rasterizerDesc.DepthClipEnable = TRUE;
		if (rasterizerState)
			rasterizerState->GetDesc(&rasterizerDesc);

		std::array<D3D11_VIEWPORT, D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE> viewports{};
		UINT viewportCount = static_cast<UINT>(viewports.size());
		a_context->RSGetViewports(&viewportCount, viewports.data());
		std::string viewportText;
		for (uint32_t index = 0; index < viewportCount; ++index) {
			if (!viewportText.empty())
				viewportText += ';';
			const auto& viewport = viewports[index];
			viewportText += std::format(
				"{}({:.3f},{:.3f},{:.3f},{:.3f},{:.6f},{:.6f})",
				index,
				viewport.TopLeftX,
				viewport.TopLeftY,
				viewport.Width,
				viewport.Height,
				viewport.MinDepth,
				viewport.MaxDepth);
		}

		std::array<D3D11_RECT, D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE> scissors{};
		UINT scissorCount = static_cast<UINT>(scissors.size());
		a_context->RSGetScissorRects(&scissorCount, scissors.data());
		std::string scissorText;
		for (uint32_t index = 0; index < scissorCount; ++index) {
			if (!scissorText.empty())
				scissorText += ';';
			const auto& scissor = scissors[index];
			scissorText += std::format(
				"{}({},{},{},{})",
				index,
				scissor.left,
				scissor.top,
				scissor.right,
				scissor.bottom);
		}

		D3D11_PRIMITIVE_TOPOLOGY topology = D3D11_PRIMITIVE_TOPOLOGY_UNDEFINED;
		a_context->IAGetPrimitiveTopology(&topology);
		std::array<ID3D11UnorderedAccessView*, D3D11_PS_CS_UAV_REGISTER_COUNT> uavs{};
		a_context->OMGetRenderTargetsAndUnorderedAccessViews(
			0,
			nullptr,
			nullptr,
			0,
			static_cast<UINT>(uavs.size()),
			uavs.data());
		auto releaseUAVs = ScopeExit([&]() {
			for (auto* uav : uavs) {
				if (uav)
					uav->Release();
			}
		});
		std::string uavText;
		for (uint32_t index = 0; index < uavs.size(); ++index) {
			if (!uavs[index])
				continue;
			if (!uavText.empty())
				uavText += ';';
			uavText += std::format("{}:{}", index, DescribeVRMenuPresentationTraceView(uavs[index]));
		}
		std::array<ID3D11UnorderedAccessView*, D3D11_PS_CS_UAV_REGISTER_COUNT> computeUAVs{};
		a_context->CSGetUnorderedAccessViews(
			0,
			static_cast<UINT>(computeUAVs.size()),
			computeUAVs.data());
		auto releaseComputeUAVs = ScopeExit([&]() {
			for (auto* uav : computeUAVs) {
				if (uav)
					uav->Release();
			}
		});
		std::string computeUAVText;
		for (uint32_t index = 0; index < computeUAVs.size(); ++index) {
			if (!computeUAVs[index])
				continue;
			if (!computeUAVText.empty())
				computeUAVText += ';';
			computeUAVText += std::format(
				"{}:{}",
				index,
				DescribeVRMenuPresentationTraceView(computeUAVs[index]));
		}

		return std::format(
			"blend(state=0x{:X},default={},alphaToCoverage={},independent={},factor=[{:.6f},{:.6f},{:.6f},{:.6f}],sampleMask=0x{:X},targets=[{}]) rasterizer(state=0x{:X},default={},fill={},cull={},frontCCW={},depthBias={},depthBiasClamp={:.6f},slopeScaledDepthBias={:.6f},depthClip={},scissor={},multisample={},antialiasedLine={}) topology={} viewports(count={},values=[{}]) scissors(count={},values=[{}]) uavs(om=[{}],compute=[{}]) {}",
			GetCOMIdentityAddress(blendState),
			blendState == nullptr,
			blendDesc.AlphaToCoverageEnable != FALSE,
			blendDesc.IndependentBlendEnable != FALSE,
			blendFactor[0],
			blendFactor[1],
			blendFactor[2],
			blendFactor[3],
			sampleMask,
			blendTargets,
			GetCOMIdentityAddress(rasterizerState),
			rasterizerState == nullptr,
			static_cast<uint32_t>(rasterizerDesc.FillMode),
			static_cast<uint32_t>(rasterizerDesc.CullMode),
			rasterizerDesc.FrontCounterClockwise != FALSE,
			rasterizerDesc.DepthBias,
			rasterizerDesc.DepthBiasClamp,
			rasterizerDesc.SlopeScaledDepthBias,
			rasterizerDesc.DepthClipEnable != FALSE,
			rasterizerDesc.ScissorEnable != FALSE,
			rasterizerDesc.MultisampleEnable != FALSE,
			rasterizerDesc.AntialiasedLineEnable != FALSE,
			static_cast<uint32_t>(topology),
			viewportCount,
			viewportText,
			scissorCount,
			scissorText,
			uavText.empty() ? "none" : uavText,
			computeUAVText.empty() ? "none" : computeUAVText,
			DescribeVRMenuPresentationTraceDepthState(a_context).text);
	}

	std::string DescribeVRMenuPresentationTraceDrawPipelineIdentity(ID3D11DeviceContext* a_context)
	{
		if (!a_context)
			return "drawPipeline=null-context";

		ID3D11InputLayout* inputLayout = nullptr;
		ID3D11Buffer* indexBuffer = nullptr;
		DXGI_FORMAT indexFormat = DXGI_FORMAT_UNKNOWN;
		UINT indexOffset = 0;
		a_context->IAGetInputLayout(&inputLayout);
		a_context->IAGetIndexBuffer(&indexBuffer, &indexFormat, &indexOffset);
		auto releaseIA = ScopeExit([&]() {
			if (inputLayout)
				inputLayout->Release();
			if (indexBuffer)
				indexBuffer->Release();
		});

		std::array<ID3D11Buffer*, D3D11_IA_VERTEX_INPUT_RESOURCE_SLOT_COUNT> vertexBuffers{};
		std::array<UINT, D3D11_IA_VERTEX_INPUT_RESOURCE_SLOT_COUNT> strides{};
		std::array<UINT, D3D11_IA_VERTEX_INPUT_RESOURCE_SLOT_COUNT> offsets{};
		a_context->IAGetVertexBuffers(
			0,
			static_cast<UINT>(vertexBuffers.size()),
			vertexBuffers.data(),
			strides.data(),
			offsets.data());
		auto releaseVertexBuffers = ScopeExit([&]() {
			for (auto* buffer : vertexBuffers) {
				if (buffer)
					buffer->Release();
			}
		});
		std::string vertexBufferText;
		for (uint32_t slot = 0; slot < vertexBuffers.size(); ++slot) {
			if (!vertexBuffers[slot])
				continue;
			if (!vertexBufferText.empty())
				vertexBufferText += ';';
			vertexBufferText += std::format(
				"{}(buffer=0x{:X},stride={},offset={})",
				slot,
				GetCOMIdentityAddress(vertexBuffers[slot]),
				strides[slot],
				offsets[slot]);
		}

		ID3D11VertexShader* vs = nullptr;
		ID3D11HullShader* hs = nullptr;
		ID3D11DomainShader* ds = nullptr;
		ID3D11GeometryShader* gs = nullptr;
		ID3D11PixelShader* ps = nullptr;
		ID3D11ComputeShader* cs = nullptr;
		a_context->VSGetShader(&vs, nullptr, nullptr);
		a_context->HSGetShader(&hs, nullptr, nullptr);
		a_context->DSGetShader(&ds, nullptr, nullptr);
		a_context->GSGetShader(&gs, nullptr, nullptr);
		a_context->PSGetShader(&ps, nullptr, nullptr);
		a_context->CSGetShader(&cs, nullptr, nullptr);
		auto releaseShaders = ScopeExit([&]() {
			if (vs)
				vs->Release();
			if (hs)
				hs->Release();
			if (ds)
				ds->Release();
			if (gs)
				gs->Release();
			if (ps)
				ps->Release();
			if (cs)
				cs->Release();
		});

		std::array<ID3D11Buffer*, D3D11_SO_BUFFER_SLOT_COUNT> streamOutputBuffers{};
		a_context->SOGetTargets(
			static_cast<UINT>(streamOutputBuffers.size()),
			streamOutputBuffers.data());
		auto releaseStreamOutputBuffers = ScopeExit([&]() {
			for (auto* buffer : streamOutputBuffers) {
				if (buffer)
					buffer->Release();
			}
		});
		std::string streamOutputText;
		for (uint32_t slot = 0; slot < streamOutputBuffers.size(); ++slot) {
			if (!streamOutputBuffers[slot])
				continue;
			if (!streamOutputText.empty())
				streamOutputText += ';';
			streamOutputText += std::format(
				"{}:0x{:X}",
				slot,
				GetCOMIdentityAddress(streamOutputBuffers[slot]));
		}

		return std::format(
			"context(identity=0x{:X},vtable=0x{:X},type={}) shaders(vs=0x{:X},hs=0x{:X},ds=0x{:X},gs=0x{:X},ps=0x{:X},cs=0x{:X},engineVS={},enginePS={}) ia(layout=0x{:X},index(buffer=0x{:X},format={},offset={}),vertexBuffers=[{}]) streamOutput=[{}]",
			reinterpret_cast<std::uintptr_t>(a_context),
			reinterpret_cast<std::uintptr_t>(*reinterpret_cast<std::uintptr_t**>(a_context)),
			static_cast<uint32_t>(a_context->GetType()),
			GetCOMIdentityAddress(vs),
			GetCOMIdentityAddress(hs),
			GetCOMIdentityAddress(ds),
			GetCOMIdentityAddress(gs),
			GetCOMIdentityAddress(ps),
			GetCOMIdentityAddress(cs),
			globals::game::currentVertexShader && *globals::game::currentVertexShader ?
				(*globals::game::currentVertexShader)->id :
				0u,
			globals::game::currentPixelShader && *globals::game::currentPixelShader ?
				(*globals::game::currentPixelShader)->id :
				0u,
			GetCOMIdentityAddress(inputLayout),
			GetCOMIdentityAddress(indexBuffer),
			static_cast<uint32_t>(indexFormat),
			indexOffset,
			vertexBufferText.empty() ? "none" : vertexBufferText,
			streamOutputText.empty() ? "none" : streamOutputText);
	}

	std::string DescribeVRMenuPresentationTracePixelShaderInputs(ID3D11DeviceContext* a_context)
	{
		if (!a_context)
			return "none";

		std::array<ID3D11ShaderResourceView*, D3D11_COMMONSHADER_INPUT_RESOURCE_SLOT_COUNT> views{};
		a_context->PSGetShaderResources(0, static_cast<UINT>(views.size()), views.data());
		auto releaseViews = ScopeExit([&]() {
			for (auto* view : views) {
				if (view)
					view->Release();
			}
		});
		std::string text;
		for (uint32_t slot = 0; slot < views.size(); ++slot) {
			if (!views[slot])
				continue;
			if (!text.empty())
				text += "; ";
			text += std::format("{}:{}", slot, DescribeVRMenuPresentationTraceView(views[slot]));
		}
		return text.empty() ? "none" : text;
	}

	std::string DescribeVRMenuPresentationTraceComputeShaderInputs(ID3D11DeviceContext* a_context)
	{
		if (!a_context)
			return "none";

		std::array<ID3D11ShaderResourceView*, D3D11_COMMONSHADER_INPUT_RESOURCE_SLOT_COUNT> views{};
		a_context->CSGetShaderResources(0, static_cast<UINT>(views.size()), views.data());
		auto releaseViews = ScopeExit([&]() {
			for (auto* view : views) {
				if (view)
					view->Release();
			}
		});
		std::string text;
		for (uint32_t slot = 0; slot < views.size(); ++slot) {
			if (!views[slot])
				continue;
			if (!text.empty())
				text += "; ";
			text += std::format("{}:{}", slot, DescribeVRMenuPresentationTraceView(views[slot]));
		}
		return text.empty() ? "none" : text;
	}

	struct VRMenuPresentationTraceCoverage
	{
		bool fullViewport = false;
		bool partialViewport = false;
		bool scissorEnabled = false;
		bool fullScissor = false;
		bool partialScissor = false;
	};

	VRMenuPresentationTraceCoverage GetVRMenuPresentationTraceCoverage(
		ID3D11DeviceContext* a_context,
		uint32_t a_width,
		uint32_t a_height)
	{
		VRMenuPresentationTraceCoverage result{};
		if (!a_context || a_width == 0 || a_height == 0)
			return result;

		std::array<D3D11_VIEWPORT, D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE> viewports{};
		UINT viewportCount = static_cast<UINT>(viewports.size());
		a_context->RSGetViewports(&viewportCount, viewports.data());
		for (uint32_t index = 0; index < viewportCount; ++index) {
			const auto& viewport = viewports[index];
			if (viewport.TopLeftX <= 0.0f && viewport.TopLeftY <= 0.0f &&
				viewport.TopLeftX + viewport.Width >= static_cast<float>(a_width) &&
				viewport.TopLeftY + viewport.Height >= static_cast<float>(a_height)) {
				result.fullViewport = true;
			}
		}
		result.partialViewport = !result.fullViewport;

		ID3D11RasterizerState* rasterizerState = nullptr;
		a_context->RSGetState(&rasterizerState);
		auto releaseRasterizerState = ScopeExit([&]() {
			if (rasterizerState)
				rasterizerState->Release();
		});
		if (rasterizerState) {
			D3D11_RASTERIZER_DESC desc{};
			rasterizerState->GetDesc(&desc);
			result.scissorEnabled = desc.ScissorEnable != FALSE;
		}
		if (!result.scissorEnabled) {
			result.fullScissor = true;
			return result;
		}

		std::array<D3D11_RECT, D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE> scissors{};
		UINT scissorCount = static_cast<UINT>(scissors.size());
		a_context->RSGetScissorRects(&scissorCount, scissors.data());
		for (uint32_t index = 0; index < scissorCount; ++index) {
			const auto& scissor = scissors[index];
			if (scissor.left <= 0 && scissor.top <= 0 &&
				scissor.right >= static_cast<LONG>(a_width) &&
				scissor.bottom >= static_cast<LONG>(a_height)) {
				result.fullScissor = true;
			}
		}
		result.partialScissor = !result.fullScissor;
		return result;
	}

	// Every tracked target may expose a primary and copy texture; retain headroom
	// for resources replaced during a DrawInterface call.
	constexpr uint32_t kVRMenuPresentationTraceMaxPassResources =
		static_cast<uint32_t>(kVRMenuPresentationTraceTargets.size()) * 2u + 16u;
	constexpr uint32_t kVRMenuPresentationTraceMaxGenerationResources = 32u;
	constexpr uint64_t kVRMenuPresentationTraceHashOffset = 14695981039346656037ull;
	constexpr uint64_t kVRMenuPresentationTraceHashPrime = 1099511628211ull;
	enum class VRMenuPresentationTraceGenerationBoundary : uint8_t
	{
		Unknown,
		FirstDraw,
		ColorClear,
		FullCopy,
		PartialCopy,
		FullResolve,
		PartialResolve,
		FullUpdate,
		PartialUpdate,
		AccumulatorEnd,
		DrawInterfaceEnd,
		FrameAdvance,
		OpenVRSubmit,
		MenuClose,
		SessionRearm,
	};

	std::string_view DescribeVRMenuPresentationTraceGenerationBoundary(
		VRMenuPresentationTraceGenerationBoundary a_boundary)
	{
		switch (a_boundary) {
		case VRMenuPresentationTraceGenerationBoundary::FirstDraw:
			return "first-draw";
		case VRMenuPresentationTraceGenerationBoundary::ColorClear:
			return "color-clear";
		case VRMenuPresentationTraceGenerationBoundary::FullCopy:
			return "full-copy";
		case VRMenuPresentationTraceGenerationBoundary::PartialCopy:
			return "partial-copy";
		case VRMenuPresentationTraceGenerationBoundary::FullResolve:
			return "full-resolve";
		case VRMenuPresentationTraceGenerationBoundary::PartialResolve:
			return "partial-resolve";
		case VRMenuPresentationTraceGenerationBoundary::FullUpdate:
			return "full-update";
		case VRMenuPresentationTraceGenerationBoundary::PartialUpdate:
			return "partial-update";
		case VRMenuPresentationTraceGenerationBoundary::AccumulatorEnd:
			return "accumulator-end";
		case VRMenuPresentationTraceGenerationBoundary::DrawInterfaceEnd:
			return "draw-interface-end";
		case VRMenuPresentationTraceGenerationBoundary::FrameAdvance:
			return "frame-advance";
		case VRMenuPresentationTraceGenerationBoundary::OpenVRSubmit:
			return "openvr-submit";
		case VRMenuPresentationTraceGenerationBoundary::MenuClose:
			return "menu-close";
		case VRMenuPresentationTraceGenerationBoundary::SessionRearm:
			return "session-rearm";
		default:
			return "unknown";
		}
	}

	struct VRMenuPresentationTraceGenerationSnapshot
	{
		bool found = false;
		uint32_t session = 0;
		uint32_t beginFrame = 0;
		uint32_t lastWriteFrame = 0;
		RE::RENDER_TARGETS::RENDER_TARGET target = RE::RENDER_TARGETS::kPROJECTEDMENU;
		std::uintptr_t resourceIdentity = 0;
		uint64_t generation = 0;
		uint64_t firstWriteSequence = 0;
		uint64_t lastWriteSequence = 0;
		uint64_t beginEpoch = 0;
		uint64_t lastWriterEpoch = 0;
		uint32_t draws = 0;
		uint32_t operations = 0;
		bool complete = false;
		VRMenuPresentationTraceGenerationBoundary beginBoundary =
			VRMenuPresentationTraceGenerationBoundary::Unknown;
		VRMenuPresentationTraceGenerationBoundary completionBoundary =
			VRMenuPresentationTraceGenerationBoundary::Unknown;
	};

	using VRMenuPresentationTraceGenerationState = VRMenuPresentationTraceGenerationSnapshot;

	std::mutex g_vrMenuPresentationTraceGenerationMutex;
	std::array<VRMenuPresentationTraceGenerationState, kVRMenuPresentationTraceMaxGenerationResources>
		g_vrMenuPresentationTraceGenerationStates{};
	std::atomic_uint64_t g_vrMenuPresentationTraceNextGeneration{ 0 };
	std::atomic_uint64_t g_vrMenuPresentationTraceNextGenerationWrite{ 0 };

	bool IsVRMenuPresentationTraceGenerationResource(const VRMenuCompositionTargetMatch& a_match)
	{
		return a_match.matched && a_match.resourceIdentity != 0 &&
		       (a_match.target == RE::RENDER_TARGETS::kPROJECTEDMENU ||
				   a_match.target == RE::RENDER_TARGETS::kHUDMENU);
	}

	VRMenuPresentationTraceGenerationState* FindVRMenuPresentationTraceGenerationStateLocked(
		const VRMenuCompositionTargetMatch& a_match,
		bool a_add)
	{
		VRMenuPresentationTraceGenerationState* freeState = nullptr;
		VRMenuPresentationTraceGenerationState* recyclableState = nullptr;
		for (auto& state : g_vrMenuPresentationTraceGenerationStates) {
			if (state.found && state.resourceIdentity == a_match.resourceIdentity && state.target == a_match.target)
				return &state;
			if (!state.found && !freeState)
				freeState = &state;
			if (state.found &&
				(!recyclableState || state.lastWriteSequence < recyclableState->lastWriteSequence)) {
				recyclableState = &state;
			}
		}
		if (!a_add)
			return nullptr;
		if (!freeState)
			freeState = recyclableState;
		if (!freeState)
			return nullptr;
		*freeState = {};
		freeState->found = true;
		freeState->target = a_match.target;
		freeState->resourceIdentity = a_match.resourceIdentity;
		return freeState;
	}

	VRMenuPresentationTraceGenerationSnapshot RecordVRMenuPresentationTraceGenerationWrite(
		const VRMenuCompositionTargetMatch& a_match,
		VRMenuPresentationTraceGenerationBoundary a_boundary,
		bool a_forceNewGeneration,
		bool a_draw)
	{
		if (!IsVRMenuPresentationTraceGenerationResource(a_match))
			return {};

		std::scoped_lock lock(g_vrMenuPresentationTraceGenerationMutex);
		auto* state = FindVRMenuPresentationTraceGenerationStateLocked(a_match, true);
		if (!state)
			return {};
		const uint32_t session = g_vrMenuPresentationTraceSession.load(std::memory_order_acquire);
		const uint32_t frame = GetVRMenuPresentationTraceFrame();
		const bool beginGeneration = a_forceNewGeneration || state->generation == 0 ||
		                             state->session != session || state->complete || state->lastWriteFrame != frame;
		if (beginGeneration) {
			const auto target = state->target;
			const auto identity = state->resourceIdentity;
			*state = {};
			state->found = true;
			state->target = target;
			state->resourceIdentity = identity;
			state->session = session;
			state->beginFrame = frame;
			state->generation =
				g_vrMenuPresentationTraceNextGeneration.fetch_add(1, std::memory_order_acq_rel) + 1u;
			state->beginEpoch = GetCurrentVRMenuPresentationTraceAccumulatorEpochId();
			state->beginBoundary = a_boundary;
		}
		const uint64_t writeSequence =
			g_vrMenuPresentationTraceNextGenerationWrite.fetch_add(1, std::memory_order_acq_rel) + 1u;
		if (state->firstWriteSequence == 0)
			state->firstWriteSequence = writeSequence;
		state->lastWriteSequence = writeSequence;
		state->lastWriteFrame = frame;
		state->lastWriterEpoch = GetCurrentVRMenuPresentationTraceAccumulatorEpochId();
		state->draws += a_draw ? 1u : 0u;
		state->operations += a_draw ? 0u : 1u;
		return *state;
	}

	VRMenuPresentationTraceGenerationSnapshot GetVRMenuPresentationTraceGeneration(
		const VRMenuCompositionTargetMatch& a_match)
	{
		if (!IsVRMenuPresentationTraceGenerationResource(a_match))
			return {};
		std::scoped_lock lock(g_vrMenuPresentationTraceGenerationMutex);
		const auto* state = FindVRMenuPresentationTraceGenerationStateLocked(a_match, false);
		return state ? *state : VRMenuPresentationTraceGenerationSnapshot{};
	}

	void CompleteVRMenuPresentationTraceGeneration(
		const VRMenuCompositionTargetMatch& a_match,
		uint64_t a_generation,
		VRMenuPresentationTraceGenerationBoundary a_boundary)
	{
		if (!IsVRMenuPresentationTraceGenerationResource(a_match) || a_generation == 0)
			return;
		std::scoped_lock lock(g_vrMenuPresentationTraceGenerationMutex);
		auto* state = FindVRMenuPresentationTraceGenerationStateLocked(a_match, false);
		if (state && state->generation == a_generation) {
			state->complete = true;
			state->completionBoundary = a_boundary;
		}
	}

	void CompleteVRMenuPresentationTraceGenerationsForEpoch(uint64_t a_epoch)
	{
		if (a_epoch == 0)
			return;
		std::scoped_lock lock(g_vrMenuPresentationTraceGenerationMutex);
		for (auto& state : g_vrMenuPresentationTraceGenerationStates) {
			if (!state.found || state.complete || state.lastWriterEpoch != a_epoch)
				continue;
			state.complete = true;
			state.completionBoundary = VRMenuPresentationTraceGenerationBoundary::AccumulatorEnd;
		}
	}

	void ResetVRMenuPresentationTraceGenerations()
	{
		std::scoped_lock lock(g_vrMenuPresentationTraceGenerationMutex);
		g_vrMenuPresentationTraceGenerationStates = {};
	}

	std::string DescribeVRMenuPresentationTraceGeneration(
		const VRMenuPresentationTraceGenerationSnapshot& a_generation)
	{
		if (!a_generation.found)
			return "generation=unobserved";
		return std::format(
			"generation={} complete={} begin={} completion={} session={} frame(begin={},lastWrite={}) writeSequence(first={},last={}) epoch(begin={},lastWriter={}) writes(draws={},operations={})",
			a_generation.generation,
			a_generation.complete,
			DescribeVRMenuPresentationTraceGenerationBoundary(a_generation.beginBoundary),
			DescribeVRMenuPresentationTraceGenerationBoundary(a_generation.completionBoundary),
			a_generation.session,
			a_generation.beginFrame,
			a_generation.lastWriteFrame,
			a_generation.firstWriteSequence,
			a_generation.lastWriteSequence,
			a_generation.beginEpoch,
			a_generation.lastWriterEpoch,
			a_generation.draws,
			a_generation.operations);
	}

	std::string DescribeVRMenuPresentationTraceCurrentGenerations()
	{
		std::scoped_lock lock(g_vrMenuPresentationTraceGenerationMutex);
		std::string result;
		const uint32_t session = g_vrMenuPresentationTraceSession.load(std::memory_order_acquire);
		for (const auto& state : g_vrMenuPresentationTraceGenerationStates) {
			if (!state.found || state.session != session)
				continue;
			if (!result.empty())
				result += "; ";
			result += std::format(
				"target={} id=0x{:X} {}",
				state.target == RE::RENDER_TARGETS::kPROJECTEDMENU ? "PROJECTEDMENU" : "HUDMENU",
				state.resourceIdentity,
				DescribeVRMenuPresentationTraceGeneration(state));
		}
		return result.empty() ? "none" : result;
	}

